import{_ as e,a as s}from"./chunks/sk_2.CVv6rsse.js";import{_ as d,c as t,o as n,ae as u}from"./chunks/framework.Cd-3tpCq.js";const _=JSON.parse('{"title":"认识soundkey","description":"MinecraftSounds 进阶教程 认识soundkey","frontmatter":{"title":"认识soundkey","description":"MinecraftSounds 进阶教程 认识soundkey"},"headers":[],"relativePath":"tutorials/soundkey.md","filePath":"tutorials/soundkey.md"}'),a={name:"tutorials/soundkey.md"};function r(c,o,y,i,k,l){return n(),t("div",null,o[0]||(o[0]=[u('<h1 id="认识soundkey" tabindex="-1">认识soundkey <a class="header-anchor" href="#认识soundkey" aria-label="Permalink to &quot;认识soundkey&quot;">​</a></h1><p>在 MinecraftSounds 中，每个音效都有一个唯一的标识符，称为 soundkey。soundkey 是一个字符串，用于在游戏中引用和播放音效。</p><p>soundkey 由两部分组成：</p><ol><li>主键：在<a href="./getting-started.html#创建新项目">创建新项目</a>的第3步时，你需要填写一个主键，这个主键会作为 soundkey 的一部分。<br><img src="'+e+'" alt="soundkey"></li><li>音效soundkey：在<a href="./getting-started.html#添加音效">添加音效</a>的第2步时，你添加的音频会自动生成一个soundkey<br><img src="'+s+'" alt="soundkey"></li></ol><p>由「主键」加上「音效soundkey」，就是一个完整的 soundkey。</p><p>例如，一个名为 &quot;mcsd&quot; 的主键，一个名为 &quot;my_sound&quot; 的音效soundkey，soundkey 就是 &quot;mcsd.my_sound&quot;。</p><h1 id="音效soundkey的使用" tabindex="-1">音效soundkey的使用 <a class="header-anchor" href="#音效soundkey的使用" aria-label="Permalink to &quot;音效soundkey的使用&quot;">​</a></h1><p>在 MinecraftSounds 中，你可以使用音效soundkey来引用和播放音效。</p><p>1.7.10及以下版本：<br><code>/playsound {soundkey} @a ~ ~ ~ 10000</code><br> 1.8及以上版本：<br><code>/playsound {soundkey} record @a ~ ~ ~ 10000</code></p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>在使用 soundkey 时，需要将 {soundkey} 替换为实际的 soundkey。<br> 例如：一个名为 &quot;mcsd&quot; 的主键，一个名为 &quot;my_sound&quot; 的音效soundkey，soundkey 就是 &quot;mcsd.my_sound&quot;。</p><p>1.7.10及以下版本：<br><code>/playsound mcsd.my_sound @a ~ ~ ~ 10000</code><br> 1.8及以上版本：<br><code>/playsound mcsd.my_sound record @a ~ ~ ~ 10000</code></p></div>',10)]))}const f=d(a,[["render",r]]);export{_ as __pageData,f as default};
